begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into auth.users(id) values ('00000000-0000-0000-0000-000000009101'),('00000000-0000-0000-0000-000000009102');
insert into public.worlds(id,owner_id,name,timezone) values ('90000000-0000-0000-0000-000000000101','00000000-0000-0000-0000-000000009101','RPC','UTC');
insert into public.world_members(world_id,user_id,role) values ('90000000-0000-0000-0000-000000000101','00000000-0000-0000-0000-000000009102','member');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000009101',true);
select throws_ok($$select public.send_group_chat_message('90000000-0000-0000-0000-000000000101',gen_random_uuid(),'')$$,'23514',null,'empty rejected');
select throws_ok($$select public.send_group_chat_message('90000000-0000-0000-0000-000000000101',gen_random_uuid(),E' \t\n')$$,'23514',null,'whitespace rejected');
select throws_ok($$select public.send_group_chat_message('90000000-0000-0000-0000-000000000101',gen_random_uuid(),repeat('😀',2001))$$,'23514',null,'2001 unicode rejected');
select is(public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000101',repeat('😀',2000))->>'message_seq','1','2000 codepoints accepted');
select is(public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000101',repeat('😀',2000))->>'message_seq','1','retry deduplicates');
select throws_ok($$select public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000101','different')$$,'23514',null,'request reuse with different body rejected');
select is((select nickname from public.group_chat_messages limit 1),'행성 동기화 대기','missing profile fallback');
select is(public.get_group_chat_context('90000000-0000-0000-0000-000000000101')->>'unread_count','0','own messages excluded from unread');
select throws_ok($$select public.mark_group_chat_read('90000000-0000-0000-0000-000000000101',2)$$,'23514',null,'future read rejected');
select is(public.mark_group_chat_read('90000000-0000-0000-0000-000000000101',1)->>'last_read_seq','1','read cursor advances');
select throws_ok($$select public.mark_group_chat_read('90000000-0000-0000-0000-000000000101',0)$$,'23514',null,'read regression rejected');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000009102',true);
select is(public.get_group_chat_context('90000000-0000-0000-0000-000000000101')->>'unread_count','1','other messages unread');
select throws_ok($$select public.delete_group_chat_message('90000000-0000-0000-0000-000000000101',(select id from public.group_chat_messages limit 1))$$,'42501',null,'other author cannot delete');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000009101',true);
select is(public.delete_group_chat_message('90000000-0000-0000-0000-000000000101',(select id from public.group_chat_messages limit 1))->>'body',null,'delete clears body');
select is(public.delete_group_chat_message('90000000-0000-0000-0000-000000000101',(select id from public.group_chat_messages limit 1))->>'change_seq','2','repeat delete does not bump cursor');
select is(public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000101',repeat('😀',2000))->>'body',null,'retry cannot restore deleted body');
select is(jsonb_array_length(public.sync_group_chat_changes('90000000-0000-0000-0000-000000000101',1,2,50)->'messages'),1,'changes recover tombstone');
select is(jsonb_array_length(public.list_group_chat_messages('90000000-0000-0000-0000-000000000101',null,50)->'messages'),1,'list includes tombstone');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000009102',true);
select is(public.get_group_chat_context('90000000-0000-0000-0000-000000000101')->>'unread_count','0','tombstones excluded from unread');
reset role;
insert into public.planet_member_state(user_id,nickname,avatar,timezone,current_cycle_id,cycle_started_at,current_planet_tokens,lifetime_tokens,growth_credit,stage,progress_to_next,incomplete,shared_visible)
values('00000000-0000-0000-0000-000000009102','Paused author','feminine','UTC','chat-test',now(),123,456,0,0,0,false,false);
set local role authenticated;
select is(public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000102','한글')->>'nickname','Paused author','paused profile snapshot is server-owned');
select is((select avatar from public.group_chat_messages where message_seq=2),'feminine','pixel avatar snapshot preserved');
reset role;
select is((select shared_visible from public.planet_member_state where user_id='00000000-0000-0000-0000-000000009102'),false,'chat does not resume sharing');
select is((select current_planet_tokens from public.planet_member_state where user_id='00000000-0000-0000-0000-000000009102'),123::bigint,'chat does not change token stats');
update public.planet_member_state set nickname='Changed' where user_id='00000000-0000-0000-0000-000000009102';
set local role authenticated;
select is(public.send_group_chat_message('90000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000103','new')->>'nickname','Changed','new message captures new profile');
reset role;
delete from auth.users where id='00000000-0000-0000-0000-000000009102';
select is((select nickname from public.group_chat_messages where message_seq=2),'Paused author','Auth deletion preserves old snapshot and body');
select * from finish(); rollback;
